// Generates the IMPROVED narration for the English demo via real Sarvam TTS:
// each scene is split into short natural phrases (long single-breath TTS
// utterances are what read as robotic) and written as NN-p0.wav, NN-p1.wav,
// etc., plus a manifest.json listing them per scene.
//
// script.js currently plays the OLDER single-clip-per-scene files
// (01-hook.wav, 02-intro.wav, ...) that are already sitting in audio/ and
// were generated by an earlier version of this script. This new phrase-split
// version was blocked by a Sarvam "insufficient_quota_error" (account out of
// credits) the last time it was run, so those NN-pN.wav files don't exist
// yet — do NOT point script.js at them until you've actually run this and
// confirmed the files are there.
//
// To upgrade once Sarvam credits are available:
//   1. node public/demo/generate-audio.js   (regenerates audio/*-pN.wav + manifest.json)
//   2. In script.js's runSequence(), change each step's `clip: 'NN-hook'` to
//      `clips: ['NN-hook-p0', 'NN-hook-p1', ...]` (see manifest.json for the
//      exact list per scene) and update playClip's call site to loop over
//      the array, awaiting each in turn.

require('dotenv').config();
const fs = require('fs');
const path = require('path');

const API_KEY = process.env.SARVAM_API_KEY;
const OUT_DIR = path.join(__dirname, 'audio');
const SARVAM_TTS_URL = 'https://api.sarvam.ai/text-to-speech';

if (!fs.existsSync(OUT_DIR)) fs.mkdirSync(OUT_DIR, { recursive: true });

// scene id -> array of [speaker, language_code, pace, pitch, text] phrases,
// each rendered as scene-NN.wav (00, 01, 02...) and played back to back.
// pitch must be within [-0.5, 0.5] for Bulbul v3/v4 — kept subtle on purpose,
// just enough to break up monotone delivery across phrases.
const scenes = {
  '01-hook': [
    ['aditya', 'en-IN', 0.95, -0.15, 'Every day, property leads come in on WhatsApp, Instagram, Facebook, and phone calls.'],
    ['aditya', 'en-IN', 0.92, 0, 'And every message you miss...'],
    ['aditya', 'en-IN', 0.9, 0.15, 'is a sale you lose.'],
  ],
  '02-intro': [
    ['aditya', 'en-IN', 0.95, 0, 'Meet Realty AI.'],
    ['aditya', 'en-IN', 0.95, -0.15, 'An AI sales employee that answers instantly, understands exactly what your customer needs...'],
    ['aditya', 'en-IN', 0.92, 0.15, 'and never sleeps.'],
  ],
  '03-whatsapp-lead': [
    ['aditya', 'en-IN', 0.95, 0, "Watch what happens the moment a lead messages on WhatsApp."],
  ],
  '04-ai-reply': [
    ['ritu', 'en-IN', 1.0, 0, 'Hi! We have Skyline Heights in Sector 150, Noida.'],
    ['ritu', 'en-IN', 1.0, 0, 'Three B H K units between one point two five, and one point three five crore.'],
    ['ritu', 'en-IN', 1.02, 0.15, 'Would you like to schedule a site visit?'],
  ],
  '05-voice-intro': [
    ['aditya', 'en-IN', 0.95, 0, 'It even answers phone calls.'],
    ['aditya', 'en-IN', 0.88, -0.15, 'Live. In real time.'],
  ],
  '06-voice-greeting': [
    ['ritu', 'hi-IN', 1.0, 0, 'Namaste! Main Realty A I hoon, Skyline Realty ki taraf se.'],
    ['ritu', 'hi-IN', 1.0, 0.15, 'Aap kaisi property dekh rahe hain?'],
  ],
  '07-booking-intro': [
    ['aditya', 'en-IN', 0.95, 0, "When a customer's ready, Realty AI books the site visit instantly."],
    ['aditya', 'en-IN', 0.92, 0, "Straight onto your team's calendar."],
    ['aditya', 'en-IN', 0.9, -0.15, 'No back and forth.'],
  ],
  '08-dashboard': [
    ['aditya', 'en-IN', 0.95, 0, 'Every lead. Every conversation. Every booking.'],
    ['aditya', 'en-IN', 0.92, 0.15, 'Live, in one dashboard.'],
  ],
  '09-closing': [
    ['aditya', 'en-IN', 0.9, 0, 'Realty AI.'],
    ['aditya', 'en-IN', 0.88, 0, 'Always on. Always selling.'],
    ['aditya', 'en-IN', 0.86, -0.15, "Let's put your sales on autopilot."],
  ],
};

async function generateClip(id, speaker, language_code, pace, pitch, text) {
  const res = await fetch(SARVAM_TTS_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'api-subscription-key': API_KEY },
    body: JSON.stringify({
      inputs: [text],
      target_language_code: language_code,
      speaker,
      pace,
      pitch,
      loudness: 1.0,
      speech_sample_rate: 24000,
      enable_preprocessing: true,
      model: 'bulbul:v3',
    }),
  });
  if (!res.ok) {
    const errText = await res.text();
    throw new Error(`${id}: ${res.status} ${errText}`);
  }
  const data = await res.json();
  const audioBase64 = data?.audios?.[0];
  if (!audioBase64) throw new Error(`${id}: no audio returned`);
  const buf = Buffer.from(audioBase64, 'base64');
  fs.writeFileSync(path.join(OUT_DIR, `${id}.wav`), buf);
  console.log(`OK  ${id}.wav (${buf.length} bytes)`);
}

(async () => {
  const manifest = {};
  for (const [sceneId, phrases] of Object.entries(scenes)) {
    manifest[sceneId] = phrases.map((_, i) => `${sceneId}-p${i}`);
    for (let i = 0; i < phrases.length; i++) {
      const [speaker, lang, pace, pitch, text] = phrases[i];
      const clipId = `${sceneId}-p${i}`;
      try {
        await generateClip(clipId, speaker, lang, pace, pitch, text);
      } catch (err) {
        console.error(`FAIL ${clipId}:`, err.message);
      }
    }
  }
  fs.writeFileSync(path.join(OUT_DIR, 'manifest.json'), JSON.stringify(manifest, null, 2));
  console.log('manifest.json written');
})();
